import{_ as n,l as i,o as e,c as s,v as t,p as c,x as o,d as l,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"MVCC 版本回收","description":"","frontmatter":{"title":"MVCC 版本回收","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mvcc-gc.md","filePath":"cs/mvcc-gc.md","lastUpdated":1789023840000}'),m={name:"cs/mvcc-gc.md"};function u(h,a,C,_,E,B){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="mvcc-版本回收" tabindex="-1">MVCC 版本回收 <a class="header-anchor" href="#mvcc-版本回收" aria-label="Permalink to &quot;MVCC 版本回收&quot;">​</a></h1><div class="epigraph"><p>旧版本必须活到所有可能读它的快照结束；GC 的水位是最小活跃快照，不是「提交了就能删」。</p><footer>—— 据 Reed MVCC；Bernstein；Postgres vacuum 与 InnoDB purge 对照</footer></div><p><a href="/cs/wait-for-graph">上一课</a>处理锁等待环。本课不 DFS。缺口是版本存储的寿命：主干 MVCC 点到 GC。进阶钉水位线：<code>min(活跃事务快照)</code> 之前的不可见版本才可物理回收。InnoDB purge undo、Postgres vacuum、LSM 墓碑是同一水位的不同实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只读长查询钉住旧快照，写者不断产新版本，空间与 undo 链、堆死元组一起涨。缺口是<strong>可见性与回收的耦合</strong>，不是又一种隔离级别。二次索引：指向已删版本的项也要在 GC 时摘掉，否则回表见鬼或浪费。</p><p>与 LSM compaction：墓碑不能过水位丢。与延迟物化：RID 在查询中仍用，不能回收那一槽。</p><p><span class="marginnote">水位可全局 xmin，或每索引、每分区。autovacuum/purge 线程是实现。本课合同：GC ≤ 最小读者需要。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护活跃快照集合。GC 线程扫 undo/堆/SST，删版本。跳过仍可见页（可见性映射）。监控：oldest xmin 年龄、undo 体积、堆膨胀——超阈则杀长查询或拒绝新快照（极端）。</p><p>只读事务下一课可走不挡写的快照副本，但若仍注册全局 xmin 一样挡。</p>',10)),(e(),c(p,null,{default:o(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SNAP%5B%22%E6%B4%BB%E8%B7%83%E5%BF%AB%E7%85%A7%E9%9B%86%E5%90%88%22%5D%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%20xmin%20%2F%20ts%22%5D%0A%20%20MIN%20--%3E%20GC%5B%22%E5%9B%9E%E6%94%B6%E6%9B%B4%E6%97%A7%E4%B8%8D%E5%8F%AF%E8%A7%81%E7%89%88%E6%9C%AC%22%5D%0A%20%20LONG%5B%22%E9%95%BF%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20MIN%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SSI 只读豁免若仍占 xmin 则无豁免于 GC。复制槽、逻辑解码消费者也是「读者」，会钉 WAL 与版本。备份热快照同样。</p><p>性能：GC 写 WAL、抢 I/O，与 2Q 扫描污染叠加。节流是运维。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲只读事务的特殊快照安装。也不把 GC 当检查点。检查点是 redo 起点，GC 是版本空间。</p><p>后课默认：版本回收水位=最小快照。只读事务与快照：减少锁，仍可能钉水位，除非快照导出到不挡主库 GC 的副本。</p><p>没有水位的「立即覆盖」会让快照读到半新行或空洞。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GC 受最小活跃快照约束；长读者导致膨胀。</li><li>undo/堆/LSM 墓碑是同一水位的不同口袋。</li><li>只读事务与快照下一课。</li><li>出处：Reed；Bernstein；vacuum/purge 实践。</li></ul>',9))])}const S=n(m,[["render",u]]);export{f as __pageData,S as default};
